for kind, text in content:
    if kind == "h":
        p = doc.add_paragraph()
        run = p.add_run(text)
        run.bold = True
        run.font.size = Pt(14)
        run.font.name = 'Arial'
    elif kind == "b":
        p = doc.add_paragraph()
        run = p.add_run(text)
        run.bold = True
        run.font.name = 'Arial'
    else:
        doc.add_paragraph(text)

